"use client"

import * as React from "react"
import { cn } from "cn"

import { Button } from "@/components/standard/button"

function Dialog({
  className,
  title,
  description,
  trigger = "Open",
  children,
  ...props
}: Omit<React.ComponentProps<"dialog">, "title"> & {
  title: string
  description?: string
  trigger?: React.ReactNode
}) {
  const ref = React.useRef<HTMLDialogElement>(null)

  function openDialog() {
    ref.current?.showModal()
  }

  function closeDialog() {
    ref.current?.close()
  }

  return (
    <div data-slot="dialog-root" className="inline-flex">
      <Button tone="outline" onClick={openDialog}>
        {trigger}
      </Button>
      <dialog
        data-slot="dialog"
        className={cn(
          "m-auto w-[min(100%,24rem)] rounded-xl border border-border bg-background p-4 text-foreground shadow-lg backdrop:bg-black/50",
          className
        )}
        {...props}
        ref={ref}
      >
        <div className="flex flex-col gap-3">
          <h2 className="text-base font-semibold">{title}</h2>
          {description ? (
            <p className="text-sm text-muted-foreground">{description}</p>
          ) : null}
          {children}
          <Button tone="outline" onClick={closeDialog}>
            Close
          </Button>
        </div>
      </dialog>
    </div>
  )
}

export { Dialog }
